import re
data=open('/tmp/speech.log','rb').read().decode('utf-8','replace')
frames=[re.sub(r'\x1b\[[0-9;?]*[a-zA-Z]','',f) for f in data.split('\x1b[H') if '总电平' in f]
rows=[]
for i,c in enumerate(frames):
    m=re.search(r'总电平 \[[^\]]*\] *(-?[\d.]+) dBFS *(\S+)',c)
