        mm=re.search(re.escape(label)+r'\s+\w*\[[^\]]*\] *([\d.]+)%',c)
        if mm: bands[label]=float(mm.group(1))
    f0=re.search(r'主频 *([\d.]+) Hz *(\S+)',c)
    cen=re.search(r'质心\(50Hz-8k\) *([\d.]+) Hz',c)
    rows.append({'t':i*0.2,'lvl':float(m.group(1)),'st':m.group(2),'bands':bands,
                 'f0':float(f0.group(1)) if f0 else 0,'note':f0.group(2) if f0 else '-',
                 'cen':float(cen.group(1)) if cen else 0})
loud=[r for r in rows if r['lvl']>-60]; quiet=[r for r in rows if r['lvl']<-72]
print("有声帧 %d，安静帧 %d\n"%(len(loud),len(quiet)))
